python3 - <<'EOF'
import os,re,collections
root='AlgebraicJacobian'
imports={}
for dp,_,fns in os.walk(root):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn)
            mod=p[:-5].replace('/','.')
            deps=[]
            for line in open(p):
                m=re.match(r'^import\s+(\S+)',line)
                if m: deps.append(m.group(1))
                elif line.strip().startswith('/-') or line.strip().startswith('theorem'): pass
            imports[mod]=deps
def closure(m,seen=None):
    if seen is None: seen=set()
    for d in imports.get(m,[]):
        if d not in seen:
            seen.add(d); closure(d,seen)
    return seen
tgt='AlgebraicJacobian.Curve.GeometricallyReduced'
for m in ['AlgebraicJacobian.Picard.Pic0Et','AlgebraicJacobian.Jacobian','AlgebraicJacobian.Picard.Pic0EtStructure']:
    c=closure(m)
    print(m, '->', tgt in c, '| closure size', len(c))
EOF

